p.write_text('''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Flood-fill the background connected to the grid border. Any remaining
    # background cells are enclosed by the figure and become the interior color.
    seen = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 6 and (r, c) not in seen:
                seen.add((r, c)); q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 6 and (r, c) not in seen:
                seen.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 6 and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6 and (r,c) not in seen:
                out[r][c] = 4
    return out
''')
